// Synthetic fixture check (not part of graded tests): verify reset preserves
// successful search state per task description.
import { SearchController } from './search.mjs';

const delay = (ms, v) => new Promise(r => setTimeout(() => r(v), ms));

// 1) Older response must not overwrite newer query
{
  const c = new SearchController((q, p) => delay(q === 'old' ? 50 : 5, [q + '-row']));
  const p1 = c.search('old');
  const p2 = c.search('new');
  await Promise.all([p1, p2]);
  console.assert(JSON.stringify(c.rows) === '["new-row"]', 'stale overwrite', c.rows);
  console.assert(c.query === 'new' && c.page === 1 && c.loading === false, 'state', c);
}

// 2) Request completing after reset must not repopulate cleared rows
{
  const c = new SearchController(() => delay(30, ['late']));
  const p = c.search('term', 3);
  c.reset();
  await p;
  console.assert(JSON.stringify(c.rows) === '[]', 'reset repopulated', c.rows);
  console.assert(c.loading === false, 'loading after reset');
}

// 3) Successful search after reset still works
{
  const c = new SearchController(() => delay(1, ['ok']));
  await c.search('a');
  c.reset();
  await c.search('b', 2);
  console.assert(JSON.stringify(c.rows) === '["ok"]', 'post-reset search', c.rows);
  console.assert(c.query === 'b' && c.page === 2, 'post-reset state', c);
}

console.log('extra checks done');
